async function api(path, options = {}) {
  const config = { credentials:"same-origin", ...options };
  const scopeSensitive=["/api/v1/inventory/aging","/api/v1/policy/summary","/api/v1/anomaly/list","/api/v1/action/list"];
  if ((!config.method||config.method==="GET")&&scopeSensitive.includes(path)) path=`${path}${filterQuery()}`;
  if (config.body && typeof config.body !== "string") { config.headers = { "Content-Type":"application/json", ...(config.headers || {}) }; config.body = JSON.stringify(config.body); }
  const response = await fetch(path, config), data = await response.json().catch(() => ({}));
  if (response.status === 401) { showLogin(); throw new Error("请先登录"); }
  if (!response.ok) throw new Error(data.message || data.error || "请求失败");
  return data;
}
function escapeHtml(value) { return String(value ?? "").replace(/[&<>'"]/g, char => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char])); }
function fmt(value, digits = 0) { if (value == null || value === "") return "待接入"; const number=Number(value); return Number.isFinite(number) ? number.toLocaleString("zh-CN",{maximumFractionDigits:digits}) : String(value); }
function list(value) { return Array.isArray(value) ? value : []; }
function valueByCode(payload, code) { return list(payload?.data).find(item => item.code === code)?.value ?? null; }
function filterQuery() { const names={businessUnit:"business_unit",channel:"channel",store:"store",start:"start",end:"end",compare:"compare"}, query=new URLSearchParams();Object.entries(names).forEach(([key,name])=>{if(state.filters[key]&&state.filters[key]!=="none")query.set(name,state.filters[key]);});return query.toString()?`?${query}`:""; }
function isAdmin() { return list(state.user?.scopes).some(scope => ["review:view","sandbox:view","api:inspect"].includes(scope)); }
function businessUnitLabel(value) { return value || "全部"; }
function dataStateText() { return "指标按当前经营范围展示，未接入项不生成数字。"; }
function pending(text="待接入") { return `<span class="pending-text">${escapeHtml(text)}</span>`; }
function emptyState(title="待接入", text="真实数据接入并通过确认后展示") { return `<div class="empty"><strong>${escapeHtml(title)}</strong><span>${escapeHtml(text)}</span></div>`; }
function sectionTitle(title, sub="", actions="") { return `<div class="section-title"><div><h2>${escapeHtml(title)}</h2>${sub?`<p>${escapeHtml(sub)}</p>`:""}</div><div class="section-actions">${actions}</div></div>`; }
function panel(title, body, extra="") { return `<section class="panel"><div class="panel-head"><h3>${escapeHtml(title)}</h3>${extra}</div><div class="panel-body ${body.includes('class="table-shell"')?"flush":""}">${body}</div></section>`; }
function displayBusinessCode(value) { const text=String(value??"");return state.context?.demo_mode?text.replace(/^DEMO-/i,"").replace(/演示/g,"").replace(/\s{2,}/g," ").trim():text; }
function sanitizeBusinessDemoCopy(root) { if(!state.context?.demo_mode||adminRoutes.has(state.route))return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{node.nodeValue=node.nodeValue.replace(/DEMO[-_]?/gi,"").replace(/演示/g,"").replace(/\s{2,}/g," ");}); }
function skuLink(sku,label=null) { return sku ? `<a class="sku-link" href="/cx/sku?sku=${encodeURIComponent(sku)}" data-sku="${escapeHtml(sku)}">${escapeHtml(label??displayBusinessCode(sku))}</a>` : "—"; }
function routeLink(path,label) { return `<a class="text-link" href="${path}" data-app-link>${escapeHtml(label)} <span>→</span></a>`; }
function statusClass(value) { const text=String(value||"");if (/严重|高|逾期|落后/.test(text)) return "risk";if (/关注|中|待确认|待到货|待分配|接近/.test(text)) return "warning";if (/正常|完成|达成|领先/.test(text)) return "success";return "info"; }
function statusTag(value) { return `<span class="tag ${statusClass(value)}">${escapeHtml(value||"待确认")}</span>`; }
function metricCard(name,value,unit="",meta="",tone="") { return `<article class="metric-card ${tone}" data-metric-name="${escapeHtml(name)}"><span>${escapeHtml(name)}</span><strong class="${value==null?"is-pending":""}">${value==null?"待接入":`${fmt(value,2)}${escapeHtml(unit)}`}</strong>${meta?`<small>${escapeHtml(meta)}</small>`:""}</article>`; }
function compactMetrics(items) { return `<div class="metric-grid">${items.map(item=>metricCard(...item)).join("")}</div>`; }
function executiveCard(title,value,unit="",meta=[],footer="",tone="") { return `<article class="executive-card ${tone}"><header><span>${escapeHtml(title)}</span><b>当前范围</b></header><strong class="executive-value ${value==null?"is-pending":""}">${value==null?"待接入":`${fmt(value,2)}${escapeHtml(unit)}`}</strong><div class="executive-meta">${meta.map(item=>`<span>${escapeHtml(item)}</span>`).join("")}</div>${footer?`<div class="executive-footer">${escapeHtml(footer)}</div>`:""}</article>`; }
function skuTrendChart(windows) { const points=[["7天",windows["7"]],["14天",windows["14"]],["28天",windows["28"]],["90天",windows["90"]]],max=Math.max(...points.map(([,value])=>Number(value)||0),1),slot=120;return `<svg class="sku-trend-svg" viewBox="0 0 500 150" role="img" aria-label="SKU销售趋势">${points.map(([label,value],index)=>{const height=Math.max(4,Math.round((Number(value)||0)/max*88)),x=50+index*slot,y=106-height;return `<g><title>${escapeHtml(label)}销量 ${fmt(value)}台</title><rect x="${x}" y="${y}" width="28" height="${height}" rx="2"></rect><text class="value" x="${x+14}" y="122">${value==null?"待接入":fmt(value)}</text><text class="label" x="${x+14}" y="140">${escapeHtml(label)}</text></g>`;}).join("")}</svg>`; }
function monthProgress(now=new Date()) { const last=new Date(now.getFullYear(),now.getMonth()+1,0).getDate(); return Math.round(now.getDate()/last*10000)/100; }
function progress(value, label="达成率", timeValue=null) { if (value==null) return emptyState("目标待接入");const safe=Math.max(0,Math.min(100,Number(value)||0));return `<div class="progress-block"><div><span>${escapeHtml(label)}</span><strong>${fmt(value,2)}%</strong></div><div class="progress-track"><progress max="100" value="${safe}" aria-label="${escapeHtml(label)} ${fmt(value,2)}%"></progress></div>${timeValue==null?"":`<small>时间进度 ${fmt(timeValue,2)}%</small>`}</div>`; }
function progressComparison(value,timeValue) { if(value==null||timeValue==null)return pending("进度待确认");const actual=Math.max(0,Math.min(100,Number(value)||0)),time=Math.max(0,Math.min(100,Number(timeValue)||0));return `<div class="comparison-progress"><svg viewBox="0 0 100 12" role="img" aria-label="完成进度 ${fmt(value,2)}%，时间参考 ${fmt(timeValue,2)}%"><rect class="comparison-track" x="0" y="4" width="100" height="4" rx="2"></rect><rect class="comparison-actual" x="0" y="4" width="${actual}" height="4" rx="2"></rect><line class="comparison-time" x1="${time}" x2="${time}" y1="1" y2="11"></line></svg><small><span>完成 ${fmt(value,2)}%</span><span>时间 ${fmt(timeValue,2)}%</span></small></div>`; }
function policyProgressStatus(item) { if(!state.context?.demo_mode)return item?.status||"正式阈值待确认";const rate=Number(item?.rate),time=Number(item?.time_progress);if(!Number.isFinite(rate)||!Number.isFinite(time))return "待确认";if(rate>=100)return "已完成";const deadline=item?.deadline?new Date(`${item.deadline}T23:59:59`):null;if(deadline&&!Number.isNaN(deadline.valueOf())&&deadline<new Date())return "严重落后";const delta=rate-time;if(delta>=0)return "领先 / 正常";if(delta>=-3)return "关注";if(delta>=-10)return "落后";return "严重落后"; }
function bindDgTabs() { const tabs=[...page.querySelectorAll("[data-dg-tab]")],panels=[...page.querySelectorAll("[data-dg-panel]")];const activate=target=>{tabs.forEach(tab=>{const active=tab.dataset.dgTab===target;tab.classList.toggle("active",active);tab.setAttribute("aria-selected",String(active));tab.tabIndex=active?0:-1;});panels.forEach(panel=>panel.hidden=panel.dataset.dgPanel!==target);};tabs.forEach((tab,index)=>{tab.addEventListener("click",()=>activate(tab.dataset.dgTab));tab.addEventListener("keydown",event=>{const keys=["ArrowLeft","ArrowRight","Home","End"];if(!keys.includes(event.key))return;event.preventDefault();const next=event.key==="Home"?0:event.key==="End"?tabs.length-1:(index+(event.key==="ArrowRight"?1:-1)+tabs.length)%tabs.length;tabs[next].focus();activate(tabs[next].dataset.dgTab);});}); }
function trendChart(rows) { if(!list(rows).length) return emptyState("销售趋势待接入");const max=Math.max(...rows.map(row=>Number(row.sales_amount)||0),1),width=700,chartHeight=132,slot=width/rows.length,barWidth=Math.min(24,slot*.52);return `<svg class="trend-svg" viewBox="0 0 700 170" role="img" aria-label="销售趋势">${rows.map((row,index)=>{const height=Math.max(8,Math.round((Number(row.sales_amount)||0)/max*chartHeight)),x=index*slot+(slot-barWidth)/2,y=142-height;return `<g><title>${escapeHtml(row.date)} · ${fmt(row.sales_amount)}元</title><rect x="${x.toFixed(2)}" y="${y}" width="${barWidth.toFixed(2)}" height="${height}" rx="2"></rect><text x="${(index*slot+slot/2).toFixed(2)}" y="160">${escapeHtml(String(row.date).slice(5))}</text></g>`;}).join("")}</svg>`; }
function contributionChart(rows) { const groups={};rows.forEach(row=>{groups[row.master.business_unit]=(groups[row.master.business_unit]||0)+(Number(row.sales_windows?.["28"])||0)*(Number(row.price?.selling)||0);});const entries=Object.entries(groups).sort((a,b)=>b[1]-a[1]);if(!entries.length)return emptyState("板块贡献待接入");const max=Math.max(...entries.map(([,value])=>value),1);return `<div class="contribution-list">${entries.map(([name,value],index)=>`<div class="contribution-row"><b>0${index+1}</b><span>${escapeHtml(businessUnitLabel(name))}</span><progress max="${max}" value="${Math.max(0,value)}" aria-label="${escapeHtml(businessUnitLabel(name))}贡献"></progress><strong>${fmt(value)}元</strong></div>`).join("")}</div>`; }
function tableCell(cell) { if (cell && typeof cell === "object" && Object.hasOwn(cell,"html")) return `<td data-value="${escapeHtml(cell.sort??"")}">${cell.html}</td>`;return `<td data-value="${escapeHtml(cell??"")}">${cell==null?pending():escapeHtml(displayBusinessCode(cell))}</td>`; }
function businessTable(headers, rows, options={}) { const id=options.id||`table-${Math.random().toString(36).slice(2)}`;return `<div class="table-shell" data-business-table data-page-size="${options.pageSize||8}" id="${id}"><div class="table-tools"><label><span>搜索</span><input class="table-search" type="search" placeholder="${escapeHtml(options.placeholder||"搜索当前列表")}"></label><span class="table-count">共 ${rows.length} 条</span></div><div class="table-scroll"><table><thead><tr>${headers.map((header,index)=>`<th data-column="${index}" ${header.sortable===false?"":'class="sortable"'}>${escapeHtml(header.label||header)}</th>`).join("")}</tr></thead><tbody>${rows.map((row,index)=>`<tr data-row-index="${index}" data-search="${escapeHtml(row.map(cell=>cell&&typeof cell==="object"?(cell.search||cell.sort||""):cell).join(" ").toLowerCase())}">${row.map(tableCell).join("")}</tr>`).join("")}</tbody></table></div><div class="table-footer"><span class="table-range"></span><div><button type="button" class="table-prev">上一页</button><button type="button" class="table-next">下一页</button></div></div></div>`; }
function enhanceBusinessTables() { document.querySelectorAll("[data-business-table]").forEach(shell=>{const body=shell.querySelector("tbody"),allRows=[...body.querySelectorAll("tr")],size=Number(shell.dataset.pageSize)||8;let pageIndex=0,sortColumn=-1,ascending=true,term="";const render=()=>{let rows=allRows.filter(row=>row.dataset.search.includes(term));if(sortColumn>=0)rows.sort((a,b)=>{const av=a.children[sortColumn]?.dataset.value||"",bv=b.children[sortColumn]?.dataset.value||"",an=Number(av),bn=Number(bv),result=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:av.localeCompare(bv,"zh-CN");return ascending?result:-result;});rows.forEach(row=>body.appendChild(row));const pages=Math.max(1,Math.ceil(rows.length/size));pageIndex=Math.min(pageIndex,pages-1);allRows.forEach(row=>row.hidden=true);rows.slice(pageIndex*size,(pageIndex+1)*size).forEach(row=>row.hidden=false);shell.querySelector(".table-count").textContent=`共 ${rows.length} 条`;shell.querySelector(".table-range").textContent=rows.length?`${pageIndex*size+1}-${Math.min((pageIndex+1)*size,rows.length)} / ${rows.length}`:"暂无记录";shell.querySelector(".table-prev").disabled=pageIndex===0;shell.querySelector(".table-next").disabled=pageIndex>=pages-1;};shell.querySelector(".table-search").addEventListener("input",event=>{term=event.target.value.trim().toLowerCase();pageIndex=0;render();});shell.querySelector(".table-prev").addEventListener("click",()=>{pageIndex=Math.max(0,pageIndex-1);render();});shell.querySelector(".table-next").addEventListener("click",()=>{pageIndex+=1;render();});shell.querySelectorAll("th.sortable").forEach(th=>th.addEventListener("click",()=>{const column=Number(th.dataset.column);ascending=sortColumn===column?!ascending:true;sortColumn=column;render();}));render();}); }

function renderGlobalFilters() {
  state.filters=normalizeGlobalFilters(state.filters);
  const filters=state.filters, channels=channelsForUnit(filters.businessUnit), stores=storesForUnitChannel(filters.businessUnit,filters.channel);
    document.getElementById("globalFilters").innerHTML=`<form id="globalFilterForm"><div class="filter-group-label">业务范围</div><div class="filter-group-label date">日期与对比</div><label class="filter-business">业务板块<select name="businessUnit"><option value="">全部业务板块</option>${BUSINESS_UNITS.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("")}</select></label><label class="filter-channel">渠道<select name="channel" ${filters.businessUnit?"":"disabled"}><option value="">全部渠道</option>${channels.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("")}</select></label><label id="storeFilterLabel" class="filter-store">门店 / 店铺<select name="store" ${filters.channel&&stores.length?"":"disabled"}><option value="">全部</option>${stores.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("")}</select></label><label class="filter-start">开始日期<input name="start" type="date" value="${escapeHtml(filters.start)}"></label><label class="filter-end">结束日期<input name="end" type="date" value="${escapeHtml(filters.end)}"></label><label class="filter-compare">对比<select name="compare"><option value="none">不对比</option><option value="previous">环比/上一周期</option><option value="year_on_year">同比</option><option value="target">目标</option><option value="difference">差额</option></select></label><div class="date-shortcuts"><button type="button" data-range="today">今日</button><button type="button" data-range="yesterday">昨日</button><button type="button" data-range="week">本周</button><button type="button" data-range="month">本月</button><button type="button" data-range="custom">自定义</button></div><button class="primary filter-submit" type="submit">查询</button><button id="resetFilters" class="ghost light filter-reset" type="button">重置</button></form><small id="filterNotice">${compareNotice(filters.compare)}</small>`;
  const filterHost=document.getElementById("globalFilters"),mobileToggle=document.createElement("button");
  mobileToggle.id="mobileFilterToggle";mobileToggle.className="mobile-filter-toggle";mobileToggle.type="button";mobileToggle.textContent="筛选条件";filterHost.prepend(mobileToggle);
  const form=document.getElementById("globalFilterForm");mobileToggle.addEventListener("click",()=>{const open=form.classList.toggle("open");mobileToggle.textContent=open?"收起筛选":"筛选条件";});form.businessUnit.value=filters.businessUnit;form.channel.value=filters.channel;form.store.value=stores.includes(filters.store)?filters.store:"";form.compare.value=filters.compare;
  const resetStore=(unit,channel)=>{const next=storesForUnitChannel(unit,channel);form.store.innerHTML=`<option value="">全部</option>${next.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("")}`;form.store.disabled=!channel||!next.length;};
  form.businessUnit.addEventListener("change",()=>{const next=channelsForUnit(form.businessUnit.value);form.channel.innerHTML=`<option value="">全部渠道</option>${next.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("")}`;form.channel.disabled=!form.businessUnit.value;form.channel.value="";resetStore(form.businessUnit.value,"");});
  form.channel.addEventListener("change",()=>resetStore(form.businessUnit.value,form.channel.value));
  document.querySelectorAll("[data-range]").forEach(button=>{button.classList.toggle("active",button.dataset.range===filters.datePreset);button.addEventListener("click",()=>{const preset=button.dataset.range;if(preset!=="custom"){const range=quickDateRange(preset);form.start.value=range.start;form.end.value=range.end;}state.filters.datePreset=preset;document.querySelectorAll("[data-range]").forEach(item=>item.classList.toggle("active",item===button));});});
  [form.start,form.end].forEach(input=>input.addEventListener("change",()=>{state.filters.datePreset="custom";}));
  form.addEventListener("submit",event=>{event.preventDefault();state.filters=normalizeGlobalFilters({...Object.fromEntries(new FormData(form).entries()),datePreset:state.filters.datePreset||"custom"});sessionStorage.setItem("caixiao.globalFilters",JSON.stringify(state.filters));renderGlobalFilters();navigate(`${window.location.pathname}${window.location.search}`,false);});
  document.getElementById("resetFilters").addEventListener("click",()=>{state.filters=normalizeGlobalFilters({});sessionStorage.setItem("caixiao.globalFilters",JSON.stringify(state.filters));renderGlobalFilters();navigate(window.location.pathname,false);});
}

async function loadProductRows() { const dimensions=await api("/api/v1/dim/skus"),skus=list(dimensions.data),details=await Promise.all(skus.map(item=>api(`/api/v1/sales/sku/${encodeURIComponent(item.source_key)}${filterQuery()}`)));return details.filter(item=>item.found!==false).filter(item=>(!state.filters.businessUnit||item.master?.business_unit===state.filters.businessUnit)&&(!state.filters.channel||item.master?.channel===state.filters.channel)&&(!state.filters.store||list(item.master?.stores).includes(state.filters.store))); }
function productRisk(row) { return row.risk?.type || (Number(row.woi?.data?.[0]?.value)<2?"低库存":Number(row.woi?.data?.[1]?.value)>12?"高库存":"正常"); }
function productAction(row) { const risk=productRisk(row);return risk==="缺货"||risk==="低库存"?"补货":risk==="高库存"?"暂停采购":risk==="长库龄"?"调拨/清理":"继续观察"; }
function productSearchTags(row) { const sales28=Number(row.sales_windows?.["28"]),inv=list(row.inventory?.data),woi=list(row.woi?.data),aging=row.aging||{},tags=[productRisk(row),row.master?.lifecycle||""];if(Number.isFinite(sales28)){if(sales28>=50)tags.push("畅销");else if(sales28>0&&sales28<=20)tags.push("慢动销");else if(sales28===0)tags.push("滞销");}if(Number(inv[0]?.value)===0)tags.push("缺货");if(Number(woi[0]?.value)>0&&Number(woi[0]?.value)<2)tags.push("低库存");if(Number(woi[1]?.value)>12)tags.push("高库存");if(Number(aging["360+"])>0)tags.push("长库龄");if(row.dg_policy)tags.push("DG商品");return tags.filter(Boolean).join(" "); }
function productTableRows(rows) { return rows.map(row=>{const m=row.master||{},win=row.sales_windows||{},inv=list(row.inventory?.data),woi=list(row.woi?.data),aging=row.aging||{},risk=productRisk(row);return [{html:skuLink(m.sku),sort:m.sku,search:m.sku},m.name,m.spu,m.brand,m.channel,win["28"],inv[0]?.value,inv[1]?.value,inv[2]?.value,woi[0]?.value,woi[1]?.value,aging["90-180"],aging["360+"],row.price?.selling,row.price?.gross_margin==null?null:`${fmt(row.price.gross_margin,2)}%`,{html:statusTag(risk),sort:risk,search:productSearchTags(row)}];}); }


