function reviewItemRows(items) { return items.map(item=>`<tr data-review-id="${item.id}"><td><input class="review-select" type="checkbox" value="${item.id}" ${item.status!=="UNCONFIRMED"?"disabled":""}></td><td class="code locked">${escapeHtml(item.raw_code)}</td><td class="locked">${escapeHtml(item.raw_name)}</td><td class="locked">${escapeHtml(JSON.stringify(item.history_mapping))}</td><td>${escapeHtml(item.suggested_display_name||"—")}</td><td><input class="decision-display-name" value="${escapeHtml(item.display_name||item.suggested_display_name||"")}" ${item.status!=="UNCONFIRMED"?"disabled":""}></td><td>${statusTag(item.status)}</td><td class="code">${escapeHtml(item.version||"—")}</td></tr>`).join("") || `<tr><td colspan="8">暂无待处理对象</td></tr>`; }
async function renderReviewMapping() { const [items,versions]=await Promise.all([api("/api/v1/review/items"),api("/api/v1/review/versions")]);page.innerHTML=`<div class="admin-banner"><strong>系统管理 · 数据治理</strong><span>仅管理员与数据复核角色可见</span></div>${sectionTitle("数据映射、口径与版本管理","raw_code、raw_name、history_mapping永久只读；只有已确认并已发布的规则可进入正式指标")}${panel("确认并形成版本",`<form id="confirmForm" class="form-grid"><label>版本类型<select name="version_type"><option value="warehouse_mapping">warehouse_mapping</option><option value="channel_mapping">channel_mapping</option><option value="sku_mapping">sku_mapping</option><option value="sales_caliber">sales_caliber</option><option value="inventory_caliber">inventory_caliber</option><option value="sales_adjustment_rules">sales_adjustment_rules</option></select></label><label>版本名称<input name="version_name" value="warehouse_mapping_v1" required></label><label class="wide">确认原因<textarea name="reason" required></textarea></label><label class="wide">受影响指标<input name="affected_metrics" required></label><label class="inline-check wide"><input name="publish" type="checkbox">确认后发布</label><button class="primary wide" type="submit">确认所选对象</button><div id="confirmMessage"></div></form>`)}${sectionTitle("待处理对象")}<div class="table-scroll admin-table"><table><thead><tr><th>选择</th><th>raw_code</th><th>raw_name</th><th>history_mapping</th><th>系统建议</th><th>display_name</th><th>状态</th><th>版本</th></tr></thead><tbody>${reviewItemRows(items.data)}</tbody></table></div>${sectionTitle("版本记录")}${businessTable(["版本","类型","状态","原因","影响指标","确认人/时间","发布人/时间"].map(label=>({label})),list(versions.data).map(v=>[v.version_name,v.version_type,{html:statusTag(v.status),sort:v.status},v.reason,list(v.affected_metrics).join("、"),`${v.confirmed_by||"—"} ${v.confirmed_at||""}`,`${v.published_by||"—"} ${v.published_at||""}`]),{pageSize:10})}`;const form=document.getElementById("confirmForm");form.addEventListener("submit",async event=>{event.preventDefault();const ids=[...document.querySelectorAll(".review-select:checked")].map(node=>Number(node.value)),values=new FormData(form),decisions=ids.map(id=>{const row=document.querySelector(`[data-review-id="${id}"]`);return{item_id:id,display_name:row.querySelector(".decision-display-name").value.trim()};});try{await api("/api/v1/review/confirm",{method:"POST",body:{version_type:values.get("version_type"),version_name:values.get("version_name"),item_ids:ids,decisions,publish:values.get("publish")==="on",reason:values.get("reason"),affected_metrics:String(values.get("affected_metrics")||"").split(",").filter(Boolean)}});toast("版本已保存");await renderReviewMapping();}catch(error){document.getElementById("confirmMessage").textContent=error.message;}}); }
async function renderReviewApi() { const cards=await api("/api/v1/review/api-cards");page.innerHTML=`<div class="admin-banner"><strong>系统管理 · 数据接入</strong><span>接口配置、字段和同步策略仅供授权人员复核</span></div>${sectionTitle("数据接入状态")}<div class="api-grid">${list(cards.data).map(card=>`<article class="api-card"><div><h3>${escapeHtml(card.name)}</h3>${statusTag(card.status)}</div><p>${escapeHtml(card.purpose)}</p><dl><dt>正式端点</dt><dd>${escapeHtml(card.endpoint)}</dd><dt>鉴权</dt><dd>${escapeHtml(card.auth)}</dd><dt>分页</dt><dd>${escapeHtml(card.pagination)}</dd><dt>限流</dt><dd>${escapeHtml(card.rate_limit)}</dd><dt>同步逻辑</dt><dd>${escapeHtml(card.sync_logic)}</dd><dt>必备字段</dt><dd class="code">${escapeHtml(list(card.required_fields).join("、"))}</dd></dl></article>`).join("")}</div>${panel("销售时间字段",`<div class="time-fields">${["create_time","pay_time","audit_time","consign_time","complete_time","modified_time"].map(name=>`<span>${name}</span>`).join("")}</div>`)}`; }
async function renderSandbox() { const compare=await api("/api/v1/sandbox/compare");page.innerHTML=`<div class="admin-banner"><strong>系统管理 · 数据验证</strong><span>验证数据，不代表正式经营口径</span></div>${sectionTitle("Sandbox差异与质量验证","仅用于开发测试，与正式经营视图隔离")}<div class="two-col">${panel("销售差异",`<pre class="result-box">${escapeHtml(JSON.stringify(compare.preset?.sales||{},null,2))}</pre>`)}${panel("库存差异",`<pre class="result-box">${escapeHtml(JSON.stringify(compare.preset?.inventory||{},null,2))}</pre>`)}</div>${sectionTitle("交互比较")}${panel("输入结构化验证记录",`<form id="diffForm" class="form-grid"><label>数据域<select name="domain"><option value="sales">销售</option><option value="inventory">库存</option></select></label><label class="wide">旧记录<textarea name="old_records">[]</textarea></label><label class="wide">新记录<textarea name="new_records">[]</textarea></label><button class="primary wide" type="submit">执行比较</button><pre id="diffResult" class="result-box wide">等待输入</pre></form>`)}`;document.getElementById("diffForm").addEventListener("submit",async event=>{event.preventDefault();const values=new FormData(event.currentTarget);try{const result=await api("/api/v1/sandbox/compare",{method:"POST",body:{domain:values.get("domain"),old_records:JSON.parse(values.get("old_records")||"[]"),new_records:JSON.parse(values.get("new_records")||"[]")}});document.getElementById("diffResult").textContent=JSON.stringify(result,null,2);}catch(error){document.getElementById("diffResult").textContent=error.message;}}); }

function bindRowFilter(tableId) { const table=document.getElementById(tableId);document.querySelectorAll("[data-row-filter] button").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll("[data-row-filter] button").forEach(item=>item.classList.toggle("active",item===button));const value=button.dataset.value;table.querySelector(".table-search").value=value==="全部"?"":value;table.querySelector(".table-search").dispatchEvent(new Event("input"));})); }
function bindProductFilter() { document.querySelectorAll("[data-product-filter] button").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll("[data-product-filter] button").forEach(item=>item.classList.toggle("active",item===button));const value=button.dataset.value,input=document.querySelector("#product-table .table-search");input.value=value==="全部"?"":value==="DG商品"?"DG":value;input.dispatchEvent(new Event("input"));})); }

const renderers={home:renderHome,anomalies:renderAnomalies,priorities:renderPriorities,products:renderProducts,sku:renderSku,inventory:renderInventory,purchase:renderPurchase,transfer:renderTransfer,dg:renderDg,subsidy:renderSubsidy,policy:renderPolicy,actions:renderActions,tracking:renderTracking,"review-mapping":renderReviewMapping,"review-api":renderReviewApi,sandbox:renderSandbox};
async function navigate(path,push=true) { const cleanPath=path.split("?")[0].replace(/\/$/,"")||"/cx",requested=routeMap[cleanPath]||"home";state.route=adminRoutes.has(requested)&&!isAdmin()?"home":requested;const resolved=state.route===requested?path:"/cx/";if(push)history.pushState({},"",resolved);document.querySelectorAll("#mainNav a,.admin-nav a").forEach(link=>link.classList.toggle("active",link.dataset.route===state.route));document.getElementById("pageEyebrow").textContent=titles[state.route][0];document.getElementById("pageTitle").textContent=titles[state.route][1];document.title=`${titles[state.route][1]}｜采销经营驾驶舱`;document.getElementById("globalFilters").hidden=adminRoutes.has(state.route);page.innerHTML=emptyState("正在加载","读取已授权经营范围");try{await renderers[state.route]();sanitizeBusinessDemoCopy(page);enhanceBusinessTables();}catch(error){page.innerHTML=`<div class="callout warning"><strong>加载失败</strong><br>${escapeHtml(error.message)}</div>`;}document.querySelector(".sidebar").classList.remove("open"); }
function applyContext() { const demo=Boolean(state.context?.demo_mode);document.body.classList.toggle("demo-mode",demo);document.getElementById("demoBanner").hidden=!demo;const pill=document.getElementById("modePill");pill.hidden=demo;pill.className="status-pill formal";pill.textContent="正式数据"; }
function showLogin() { app.hidden=true;loginView.hidden=false; }
async function showApp(user) { state.user=user;document.getElementById("userName").textContent=user.username;document.getElementById("adminNav").hidden=!isAdmin();state.context=await api("/api/v1/system/context");applyContext();loginView.hidden=true;app.hidden=false;renderGlobalFilters();await navigate(`${window.location.pathname}${window.location.search}`,false); }
function toast(message) { const node=document.createElement("div");node.className="toast";node.textContent=message;document.body.appendChild(node);setTimeout(()=>node.remove(),2600); }
document.getElementById("loginForm").addEventListener("submit",async event=>{event.preventDefault();const error=document.getElementById("loginError");error.textContent="";try{await api("/api/v1/auth/login",{method:"POST",body:{username:document.getElementById("username").value,password:document.getElementById("password").value}});await showApp(await api("/api/v1/auth/me"));}catch(exception){error.textContent=exception.message;}});
document.getElementById("logoutButton").addEventListener("click",async()=>{try{await api("/api/v1/auth/logout",{method:"POST"});}finally{showLogin();}});
document.getElementById("menuButton").addEventListener("click",()=>document.querySelector(".sidebar").classList.toggle("open"));
document.getElementById("mainNav").addEventListener("click",event=>{const link=event.target.closest("a");if(link){event.preventDefault();navigate(link.getAttribute("href"));}});
document.getElementById("adminNav").addEventListener("click",event=>{const link=event.target.closest("a");if(link){event.preventDefault();navigate(link.getAttribute("href"));}});
page.addEventListener("click",event=>{const sku=event.target.closest("a.sku-link"),link=event.target.closest("a[data-app-link]");if(sku){event.preventDefault();state.selectedSku=sku.dataset.sku||"";sessionStorage.setItem("caixiao.selectedSku",state.selectedSku);navigate(sku.getAttribute("href"));}else if(link){event.preventDefault();navigate(link.getAttribute("href"));}});
window.addEventListener("popstate",()=>navigate(`${window.location.pathname}${window.location.search}`,false));
setInterval(()=>{document.getElementById("clock").textContent=new Date().toLocaleString("zh-CN",{hour12:false});},1000);
api("/api/v1/auth/me").then(showApp).catch(showLogin);
